import {Navbar, Nav} from 'react-bootstrap';
import '../navbar/Navigator.css';

function Navigator() {
  return (
    <Navbar className='navbar' collapseOnSelect expand="lg" bg="transparent" variant="dark">
      <Navbar.Brand href="/"><span className="text-danger fs-3">e</span>malgari.</Navbar.Brand>
      <Navbar.Toggle className='border border-white' aria-controls="responsive-navbar-nav" />
      <Navbar.Collapse id="responsive-navbar-nav">
        <Nav className="d-flex justify-content-center align-items-center gap-lg-5 w-100">
          <Nav.Link className='nav-link text-white fs-6' href="/">Home</Nav.Link>
          <Nav.Link className='nav-link text-white fs-6' href="about">About</Nav.Link>            
          <Nav.Link className='nav-link text-white fs-6' href="contact">Contact</Nav.Link>
        </Nav>
      </Navbar.Collapse>
    </Navbar>
  );
}

export default Navigator;
